class Solution {
  public int[] numSmallerByFrequency(String[] queries, String[] words) {
    int[] suffix = new int[12];
    for (String word : words) suffix[f(word)]++;
    for (int i = 10; i >= 1; i--) suffix[i] += suffix[i + 1];
    int[] answer = new int[queries.length];
    for (int i = 0; i < queries.length; i++) answer[i] = suffix[f(queries[i]) + 1];
    return answer;
  }

  private int f(String s) {
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) count[s.charAt(i) - 'a']++;
    for (int value : count) if (value != 0) return value;
    return 0;
  }
}
